  "base_latex_md": "\section*{Chapter 3}

\vspace{1em}
\noindent\rule{\textwidth}{0.4pt}
\vspace{1em}

\begin{center}
\Huge \textbf{Eigenvalues, Eigenfunctions,}\\
\textbf{and the Expansion Postulate}
\end{center}

\vspace{2em}

\textbf{O}ur discussion in Chapter 2 led us to the Schrödinger equation for the wave function $\psi(x, t)$ and its interpretation. In this chapter we analyze the equation in some detail. We find that for potentials $V(x)$ that do not depend on time, the equation reduces to a simple equation, the \textit{time-independent} Schrödinger equation. We solve this equation for some very simple, special cases and obtain some insights into the meaning of the solutions, which we then extend to the general case of an arbitrary potential $V(x)$.

\subsection*{3-1 THE TIME-INDEPENDENT SCHRÖDINGER EQUATION}

Let us consider the time-dependent Schrödinger equation obtained in Chapter 2,
\begin{equation}
i\hbar \frac{\partial\psi(x, t)}{\partial t} = -\frac{\hbar^2}{2m} \frac{\partial^2\psi(x, t)}{\partial x^2} + V(x)\psi(x, t) \equiv H\psi(x, t) \tag{3-1}
\end{equation}

We introduced a symbol $H$ for the operator on the right-hand side of this equation, which stands for \textit{Hamiltonian}. Equation (3-1) is a partial differential equation. Such equations are much more difficult to deal with than ordinary differential equations in one variable. In our case, because $V(x)$ does not depend on the variable $t$, it is possible to reduce the partial differential equation to two ordinary differential equations. We write
\begin{equation}
\psi(x, t) = T(t)u(x) \tag{3-2}
\end{equation}

which implies that
\[ i\hbar u(x)\frac{dT(t)}{dt} = \left\{ -\frac{\hbar^2}{2m} \frac{d^2u(x)}{dx^2} + V(x)u(x) \right\}T(t) \]

Division by $u(x)T(t)$ gives us
\begin{equation}
i\hbar \frac{1}{T(t)}\frac{dT(t)}{dt} = \frac{1}{u(x)} \left\{ -\frac{\hbar^2}{2m} \frac{d^2u(x)}{dx^2} + V(x)u(x) \right\} \tag{3-3}
\end{equation}

Since the two sides of the equation depend on different variables, this can only be satisfied if both sides are constant. We denote the constant by $E$. The solution of
\begin{equation}
i\hbar \frac{dT(t)}{dt} = E T(t) \tag{3-4}
\end{equation}

is
\begin{equation}
T(t) = C e^{-iEt/\hbar} \tag{3-5}
\end{equation}

\vspace{2em}
\noindent \textbf{44}",
